-- Migration 109 (up): the one pass that puts the posts already stored under the tag rules (internal/tagrules; new writes are cleaned as they arrive). tag_cleanup is where the pass has reached, so it resumes after a restart and never runs twice. tag_originals keeps each changed post's tags column as it was before the pass, so the pass can be undone post by post. NOTE: runMigrations executes line-by-line, so keep each statement on ONE line.
CREATE TABLE IF NOT EXISTS tag_cleanup(id INTEGER PRIMARY KEY CHECK(id=1), cursor TEXT NOT NULL DEFAULT '', scanned INTEGER NOT NULL DEFAULT 0, changed INTEGER NOT NULL DEFAULT 0, done_at DATETIME);
CREATE TABLE IF NOT EXISTS tag_originals(article_id TEXT PRIMARY KEY, tags TEXT NOT NULL, cleaned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) WITHOUT ROWID;
